import { NextResponse } from "next/server";
import { cookieName, tokenPruefen } from "@/lib/plattform/sitzung";

// Portal-Schutz: /portal/** nur mit gültig signiertem Sitzungscookie, sonst
// Weiterleitung zu /login?weiter=… (nur interne Pfade). Die Middleware prüft
// Signatur und Ablauf; Rollen, Sperre und Sitzungsversion prüfen Seiten und
// APIs bei jedem Aufruf frisch gegen das Backend.
// Sichere Kopfzeilen für Portal, Anmeldung, Einladungen und Plattform-APIs (Login, Sicherheit & Teams):
// kein Einbetten (Clickjacking), eigener Browsing-Kontext, kein Referrer bei Token-Links, HSTS in Produktion.
function sicherheitsKopf(res, pathname) {
  const h = res.headers;
  h.set("X-Frame-Options", "DENY");
  h.set("Content-Security-Policy", "frame-ancestors 'none'; base-uri 'self'; form-action 'self'; object-src 'none'");
  h.set("Cross-Origin-Opener-Policy", "same-origin");
  h.set("X-Content-Type-Options", "nosniff");
  h.set("Permissions-Policy", "camera=(), microphone=(), geolocation=(self), payment=(), usb=()");
  const tokenSeite = ["/login/link", "/einladung/", "/passwort-vergessen", "/api/auth/"].some((p) => pathname.startsWith(p));
  h.set("Referrer-Policy", tokenSeite ? "no-referrer" : "strict-origin-when-cross-origin");
  if (!pathname.startsWith("/api/")) h.set("Cache-Control", "no-store");
  if (process.env.NODE_ENV === "production") h.set("Strict-Transport-Security", "max-age=63072000; includeSubDomains");
  return res;
}

export async function middleware(request) {
  const { pathname, search } = request.nextUrl;
  // Nicht-Portal-Pfade (Anmeldung, Einladung, APIs): nur Kopfzeilen, keine Sitzungsprüfung hier
  if (pathname !== "/portal" && !pathname.startsWith("/portal/")) return sicherheitsKopf(NextResponse.next(), pathname);
  const token = request.cookies.get(cookieName())?.value;

  let gueltig = false;
  try {
    gueltig = !!(await tokenPruefen(token));
  } catch (e) {
    // z. B. SESSION_SECRET fehlt in Produktion – nie ohne Prüfung durchlassen
    console.error("[plattform] Sitzungsprüfung fehlgeschlagen:", e?.message);
  }

  if (!gueltig) {
    const ziel = new URL("/login", request.url);
    ziel.searchParams.set("weiter", `${pathname}${search}`.slice(0, 300));
    const res = NextResponse.redirect(ziel);
    if (token) res.cookies.delete(cookieName());
    return sicherheitsKopf(res, pathname);
  }

  // Aktuellen Pfad an Server-Komponenten weiterreichen (für ?weiter= bei abgelaufener Sitzung)
  const kopf = new Headers(request.headers);
  kopf.set("x-oi-pfad", `${pathname}${search}`.slice(0, 300));
  return sicherheitsKopf(NextResponse.next({ request: { headers: kopf } }), pathname);
}

export const config = {
  matcher: ["/portal", "/portal/:path*", "/login", "/login/:path*", "/registrieren", "/passwort-vergessen", "/einladung/:path*", "/api/auth/:path*", "/api/portal/:path*"],
};
// lib/apiBaseUrl.js

// API Configuration from environment variables
const SERVER = process.env.SERVER;
const API_KEY = process.env.API_KEY;
const API_SECRET = process.env.API_SECRET;

export const API_BASE_URL = `${SERVER}/api/method/`;

export function getApiHeaders() {
    if (!API_KEY || !API_SECRET) {
        console.error('Missing API credentials in environment variables');
        throw new Error('API credentials not configured');
    }

    const headers = new Headers();
    headers.append('Authorization', `token ${API_KEY}:${API_SECRET}`);
    headers.append('Content-Type', 'application/json');
    return headers;
}

// Optional: Helper function to check if API is configured
export function isApiConfigured() {
    return !!(API_KEY && API_SECRET);
}// src/lib/backendFehler.js
//
// Turns a failed Frappe response into a short German message the visitor can understand.
// Only validation messages (written by the backend for users) are passed on –
// tracebacks, module paths and other internals stay in the server log.
//
// Result codes for the browser:
//   409 vergeben    – appointment slot was booked in the meantime
//   422 validierung – the backend rejected an input (message says which)
//   429 zu_viele    – rate limit
//   502 backend     – backend not reachable / internal error

export const NICHT_ERREICHBAR = "Der Server ist vorübergehend nicht erreichbar";

const ZU_VIELE = "Zu viele Anfragen in kurzer Zeit – bitte warten Sie einen Moment";

/** Human-readable message of a Frappe ValidationError, or "" */
function validierungsText(daten) {
  if (!/ValidationError|MandatoryError/.test(String(daten?.exc_type || ""))) return "";

  let text = "";
  try {
    const liste = JSON.parse(daten._server_messages || "[]");
    text = JSON.parse(liste[0] || "{}").message || "";
  } catch {
    // _server_messages missing or not JSON – fall back to the exception line
  }
  if (!text && typeof daten.exception === "string") {
    text = daten.exception.replace(/^[\w.]*Error:\s*/, "");
  }
  return text.replace(/<[^>]*>/g, "").replace(/\s+/g, " ").trim().slice(0, 200);
}

/**
 * Reads the error body once (JSON or text), logs it on the server and returns
 * { status, body } for NextResponse.json(body, { status }).
 */
export async function backendFehler(response, kontext) {
  const text = await response.text().catch(() => "");
  let daten;
  try {
    daten = JSON.parse(text);
  } catch {
    daten = { message: text.slice(0, 500) };
  }
  console.error(`${kontext}: backend returned ${response.status}`, daten);

  const hinweis = validierungsText(daten);
  if (/nicht mehr verfügbar/i.test(hinweis)) {
    return { status: 409, body: { error: hinweis, code: "vergeben" } };
  }
  if (hinweis) {
    return { status: 422, body: { error: hinweis, code: "validierung" } };
  }
  if (response.status === 429) {
    return { status: 429, body: { error: ZU_VIELE, code: "zu_viele" } };
  }
  return { status: 502, body: { error: NICHT_ERREICHBAR, code: "backend" } };
}
// src/lib/ipAdresse.js
//
// IP-Adresse des Besuchers für den Nachweis von Anfragen/Einwilligungen (Feld „ip_adresse“ in Frappe).
// Immer serverseitig ermitteln – nie einen Wert aus dem Formular übernehmen.

/** IP-Adresse aus der Anfrage (hinter Proxy/Load-Balancer aus X-Forwarded-For bzw. X-Real-IP). */
export function ipAdresse(request) {
  const ip = request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() || request.headers.get("x-real-ip")?.trim() || "";
  return /^[0-9a-f.:]{3,45}$/i.test(ip) ? ip : "";
}
